ssize_t rio_readn(int fd, void *usrbuf, size_t n) {
    size_t nleft = n;
    ssize_t nread;
    char *bufp = usrbuf;

    while (nleft > 0) {
        if ((nread = read(fd, bufp, nleft)) < 0) {
            if (errno == EINTR) continue; // ECF: Interrupted by signal
            return -1; // ECF: Fatal syscall error
        }
        if (nread == 0) break; // ECF: End of file (EOF)

        nleft -= nread;
        bufp += nread;
    }
    return (n - nleft);
