#define MATRIX_SIZE 1024

// 1. Spatial Locality: GOOD access pattern (C/C++ Row-Major)
// Ensures cache line is fully utilized before moving on.
int mat[MATRIX_SIZE][MATRIX_SIZE];

void spatial_good() {
    for (int i = 0; i < MATRIX_SIZE; i++) {
        for (int j = 0; j < MATRIX_SIZE; j++) {
            mat[i][j] = i + j; // Adjacent access
        }
    }
}

// 2. Spatial Locality: POOR access pattern (High Stride)
// Forces immediate cache line replacement (cache misses).
void spatial_bad() {
    for (int j = 0; j < MATRIX_SIZE; j++) {
        for (int i = 0; i < MATRIX_SIZE; i++) {
            // Strides by MATRIX_SIZE * sizeof(int) bytes
            mat[i][j] = i + j;
        }
    }
}

// 3. Temporal Locality: Cache Blocking/Tiling
// Reuses sub-matrix elements (A_block, B_block) multiple times
// while they reside in faster L1/L2 cache.
#define BLOCK 32

void blocked_mm(int N, int A[N][N], int B[N][N], int C[N][N]) {
    for (int kk = 0; kk < N; kk += BLOCK) {
        for (int jj = 0; jj < N; jj += BLOCK) {
            for (int i = 0; i < N; i++) {
                // Focus: Blocked inner loops
                for (int k = kk; k < kk + BLOCK; k++) {
                    for (int j = jj; j < jj + BLOCK; j++) {
                        C[i][j] += A[i][k] * B[k][j];
                    }
                }
            }
        }
    }
}

