public:
    ResourceOwner(int v) : data(new int(v)) {}

    // 1. Destructor (Manages resource lifetime)
    ~ResourceOwner() { delete data; }

    // 2. Copy Constructor (Performs deep copy)
    ResourceOwner(const ResourceOwner& other)
        : data(other.data ? new int(*other.data) : nullptr) {}

    // 3. Copy Assignment Operator (Handles self-assign, cleanup, deep copy)
    ResourceOwner& operator=(const ResourceOwner& other) {
