class LRUCache {
    int capacity;
    using KVP = std::pair<int, int>;
    std::list<KVP> recency;
    std::unordered_map<int, std::list<KVP>::iterator> index;

public:
    LRUCache(int cap) : capacity(cap) {}

    int get(int key) {
        if (!index.count(key)) return -1;
        recency.splice(recency.begin(), recency, index[key]);
        return index[key]->second;
    }

    void put(int key, int value) {
        if (index.count(key)) {
            index[key]->second = value;
            recency.splice(recency.begin(), recency, index[key]);
        } else {
            recency.push_front({key, value});
            index[key] = recency.begin();

            if (recency.size() > capacity) {
                index.erase(recency.back().first);
                recency.pop_back();
            }
        }
    }
};

