// Simplified Pipeline Latches (Stage Registers)
struct StageReg {
    int RegDst;        // Destination Register ID
    int ResultData;
    bool RegWriteEn;   // Write back enabled?
};

StageReg EX_MEM; // Data available at EX->MEM boundary
StageReg MEM_WB; // Data available at MEM->WB boundary

// Forwarding Unit Logic defines source selection for ALU inputs
#define FWD_NONE 0
#define FWD_EX_MEM 1
#define FWD_MEM_WB 2

// Function checks if required register (R) can be bypassed
int ForwardingPath(int R) {
    // Priority 1: Check EX/MEM latch (newest data)
    if (R == EX_MEM.RegDst && EX_MEM.RegWriteEn)
        return FWD_EX_MEM;

    // Priority 2: Check MEM/WB latch
    if (R == MEM_WB.RegDst && MEM_WB.RegWriteEn)
        return FWD_MEM_WB;

    return FWD_NONE; // Read from Register File
}
